idth / root.offsetWidth || 1; // the canvas may show the phone scaled\n        return { x: (r.left - R.left) / k, y: (r.top - R.top) / k, w: r.width / k, h: r.height / k };\n      } catch (err) {\n        return { x: 24, y: 262, w: 160, h: 48 };\n      }\n    };\n    const quickAt = s.quickAt || { x: 24, y: 262, w: 160, h: 48 };\n    const quickPicks = presetDefs.map((d) => {\n      const p = presetOf(d[0]);\n      const on = !!matchDef && matchDef[0] === d[0];\n      const rec = s.nights.length === 0 && d[0] === 'steady';\n      const t = pad(p.h) + ':' + pad(p.mi * 5);\n      const noun = p.n === 1 ? (nounMany === 'drinks' ? 'drink' : nounMany.replace(/es$|s$/, '')) : nounMany;\n      return {\n        name: d[1], icon: d[3], rec: rec, on: on, checked: on ? 'true' : 'false',\n        ring: on ? '#6EE7C1' : 'transparent',\n        accent: { quiet: '#5CC8F5', steady: '#6EE7C1', usual: '#FFC56B' }[d[0]],\n        summary: p.n + ' ' + noun + ' · home by ' + t + ' · ' + rides[p.ride],\n        aria: d[1] + ': ' + p.n + ' ' + noun + ', home by ' + t + ', ' + rides[p.ride] + (rec ? '. Our pick for your first night' : ''),\n        pick: () => this.setState({ plan: p.n, homeH: p.h, homeMi: p.mi, rideIdx: p.ride, lastPreset: d[0], quickOpen: false })\n      };\n    });\n    const nounFor = (n) => n === 1 ? (nounMany === 'drinks' ? 'drink' : nounMany.replace(/es$|s$/, '')) : nounMany;\n    const quickRows = presetDefs.map((d) => {\n      const p = presetOf(d[0]);\n      const t = pad(p.h) + ':' + pad(p.mi * 5);\n      return {\n        name: d[1],\n        nameDraft: (quick[d[0]] || {}).name !== undefined ? quick[d[0]].name : d[1],\n        defaultName: d[4],\n        setName: (e) => setPreset(d[0], { name: e.target.value.slice(0, 20) }),\n        icon: d[3],\n        pickIcon: () => this.setState({ iconPickFor: d[0] }),\n        nameAria: 'Name for ' + d[1],\n        iconAria: 'Symbol for ' + d[1] + '. Change',\n        accent: { quiet: '#5CC8F5', steady: '#6EE7C1', usual: